import json, re
items = json.load(open('deliverable/issues.json'))
def norm(s):
    s = s.replace('\u201c','"').replace('\u201d','"').replace('\u2019',"'").replace('\u2018',"'")
    s = re.sub(r'^\s*> ?', '', s, flags=re.M)   # strip markdown blockquote markers
    s = re.sub(r'\*\*|\*', '', s)
    return re.sub(r'\s+',' ', s)
red = norm(open('deliverable/redlines.md').read())
bad=[]
for i in items:
    for q in re.findall(r'\u201c(.+?)\u201d', i['redline']):
        for frag in [f.strip() for f in q.split('…') if len(f.strip()) > 15]:
            if norm(frag) not in red: bad.append((i['rank'], frag))
for r,f in bad: print("REAL MISMATCH rank", r, ":", f)
print("total real mismatches:", len(bad))
EOF

